class Dialog(wx.Frame):
    def layout(self):
        # Resize so the buttons fit.
        self.sizer.Fit(self)
        self.Centre()

class Admin(ModelAdmin):
    def approve(self, request, queryset):
        queryset.update(state="ok")
        self.message_user(request, "Approved")

class Chart(View):
    def on_resize(self):
        """Called when the canvas changes size."""
        self.canvas.redraw()

class Editor:
    def reload(self):
        # The buffer may not be loaded yet.
        if self.buffer is None:
            return

class Table(Widget):
    def select(self, row):
        self.current = row
        self.highlight(row)

class Form(Panel):
    def reset(self):
        # Clear every field and redraw.
        self.fields.clear()
        self.refresh()

class Player(Window):
    def show(self):
        """Make the window visible."""
        self.visible = True

class Order(Model):
    def cancel(self):
        # Only open orders can be cancelled.
        self.state = "cancelled"
        self.save()
